56: /// Maps standard channel position strings to SPA channel position constants.
57: pub fn channel_position_to_spa(pos: &str) -> u32 {
58:     match pos.trim().to_ascii_uppercase().as_str() {
59:         "MONO" => libspa::sys::SPA_AUDIO_CHANNEL_MONO,
60:         "FL" => libspa::sys::SPA_AUDIO_CHANNEL_FL,
61:         "FR" => libspa::sys::SPA_AUDIO_CHANNEL_FR,
62:         "FC" => libspa::sys::SPA_AUDIO_CHANNEL_FC,
63:         "LFE" => libspa::sys::SPA_AUDIO_CHANNEL_LFE,
64:         "SL" => libspa::sys::SPA_AUDIO_CHANNEL_SL,
65:         "SR" => libspa::sys::SPA_AUDIO_CHANNEL_SR,
66:         "FLC" => libspa::sys::SPA_AUDIO_CHANNEL_FLC,
67:         "FRC" => libspa::sys::SPA_AUDIO_CHANNEL_FRC,
68:         "RC" => libspa::sys::SPA_AUDIO_CHANNEL_RC,
69:         "RL" => libspa::sys::SPA_AUDIO_CHANNEL_RL,
70:         "RR" => libspa::sys::SPA_AUDIO_CHANNEL_RR,
71:         _ => libspa::sys::SPA_AUDIO_CHANNEL_UNKNOWN,
72:     }
73: }
