285: /// Helper function to build an SPA `ParamBuffers` POD sized for the given quantum and frame stride.
286: pub fn build_buffers_pod(quantum_frames: u32, stride: u32) -> Result<Vec<u8>, PipeWireError> {
287:     let stride = stride.max(1) as i32;
288:     let default_size = (quantum_frames.max(256) as i32).saturating_mul(stride);
289:     let min_size = 16_i32.saturating_mul(stride);
290:     let max_size = default_size.saturating_mul(4).max(131_072);
291: 
292:     let buffers_choice =
293:         libspa::pod::Value::Choice(libspa::pod::ChoiceValue::Int(libspa::utils::Choice(
294:             libspa::utils::ChoiceFlags::empty(),
295:             libspa::utils::ChoiceEnum::Range {
296:                 default: 4,
297:                 min: 2,
298:                 max: 16,
299:             },
300:         )));
301: 
302:     let size_choice =
303:         libspa::pod::Value::Choice(libspa::pod::ChoiceValue::Int(libspa::utils::Choice(
304:             libspa::utils::ChoiceFlags::empty(),
305:             libspa::utils::ChoiceEnum::Range {
306:                 default: default_size,
307:                 min: min_size,
308:                 max: max_size,
309:             },
310:         )));
311: 
312:     let props = vec![
313:         libspa::pod::Property::new(libspa::sys::SPA_PARAM_BUFFERS_buffers, buffers_choice),
314:         libspa::pod::Property::new(
315:             libspa::sys::SPA_PARAM_BUFFERS_blocks,
316:             libspa::pod::Value::Int(1),
317:         ),
318:         libspa::pod::Property::new(libspa::sys::SPA_PARAM_BUFFERS_size, size_choice),
319:         libspa::pod::Property::new(
320:             libspa::sys::SPA_PARAM_BUFFERS_stride,
321:             libspa::pod::Value::Int(stride),
322:         ),
323:     ];
324: 
325:     let obj = libspa::pod::Object {
326:         type_: libspa::utils::SpaTypes::ObjectParamBuffers.as_raw(),
327:         id: libspa::param::ParamType::Buffers.as_raw(),
328:         properties: props,
329:     };
330: 
331:     libspa::pod::serialize::PodSerializer::serialize(
332:         std::io::Cursor::new(Vec::new()),
333:         &libspa::pod::Value::Object(obj),
334:     )
335:     .map(|(cursor, _)| cursor.into_inner())
336:     .map_err(|e| PipeWireError::FormatPod(format!("{e:?}")))
337: }
