1895: impl Drop for PipeWirePcmOutput {
1896:     fn drop(&mut self) {
1897:         self.running.store(false, Ordering::SeqCst);
1898:         let ptr = self
1899:             .writer_thread
1900:             .swap(std::ptr::null_mut(), Ordering::SeqCst);
1901:         if !ptr.is_null() {
1902:             unsafe {
1903:                 drop(Box::from_raw(ptr));
1904:             }
1905:         }
1906:         if let Some(worker) = self._worker.take() {
1907:             let _ = worker.join();
