1912: impl Write for PipeWirePcmOutput {
1913:     fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
1914:         if self.producer.is_full() {
1915:             // Register current thread handle so PipeWire consumer can unpark us
1916:             if self.writer_thread.load(Ordering::Relaxed).is_null() {
1917:                 let current = Box::into_raw(Box::new(std::thread::current()));
1918:                 if self
1919:                     .writer_thread
1920:                     .compare_exchange(
1921:                         std::ptr::null_mut(),
1922:                         current,
1923:                         Ordering::SeqCst,
1924:                         Ordering::Relaxed,
1925:                     )
1926:                     .is_err()
1927:                 {
1928:                     unsafe {
1929:                         drop(Box::from_raw(current));
1930:                     }
1931:                 }
1932:             }
1933: 
1934:             // Wait with backpressure for consumer to pop a slot
1935:             let start = std::time::Instant::now();
1936:             while self.producer.is_full() {
1937:                 if !self.running.load(Ordering::Relaxed) {
1938:                     return Err(std::io::Error::new(
1939:                         std::io::ErrorKind::Interrupted,
1940:                         "PipeWire output stopped",
1941:                     ));
1942:                 }
1943:                 if start.elapsed() >= std::time::Duration::from_millis(2000) {
1944:                     self.overruns.fetch_add(1, Ordering::Relaxed);
1945:                     return Err(std::io::Error::new(
1946:                         std::io::ErrorKind::TimedOut,
1947:                         "PipeWire output queue blocked for > 2000ms",
1948:                     ));
1949:                 }
1950:                 std::thread::park_timeout(std::time::Duration::from_micros(500));
1951:             }
1952:         }
1953: 
1954:         self.producer
1955:             .push(buf.to_vec())
1956:             .map(|_| buf.len())
1957:             .map_err(|_| std::io::Error::other("Failed to push to PipeWire queue"))
1958:     }
1959: 
1960:     fn flush(&mut self) -> std::io::Result<()> {
1961:         Ok(())
1962:     }
1963: }
