1: //! Native DSD capture pacing, independent of the graph's PCM rate and quantum.
2: 
3: #[derive(Clone, Copy, Debug)]
4: pub(super) struct GraphCycle {
5:     pub id: u32,
6:     pub position: u64,
7:     pub duration: u64,
8:     pub rate_num: u32,
9:     pub rate_denom: u32,
10: }
11: 
12: impl GraphCycle {
13:     fn seconds_per_tick(self) -> Option<f64> {
14:         (self.rate_num > 0 && self.rate_denom > 0 && self.duration > 0)
15:             .then(|| self.rate_num as f64 / self.rate_denom as f64)
16:     }
17: 
18:     /// Round up to complete interleave groups. Fractional excess is accounted
19:     /// by the pacing credit, rather than accumulating input faster than real time.
20:     pub fn buffer_bytes(self, byte_rate: u32, channels: u32, interleave: u32) -> Option<u32> {
21:         self.seconds_per_tick()?;
22:         let group = interleave.max(1) as u128;
23:         let numerator = self.duration as u128 * self.rate_num as u128 * byte_rate as u128;
24:         let groups = numerator.div_ceil(self.rate_denom as u128 * group);
25:         let bytes = groups * group * channels as u128;
26:         (bytes > 0 && bytes <= i32::MAX as u128).then_some(bytes as u32)
27:     }
28: }
29: 
30: #[derive(Debug, Default)]
31: pub(super) struct DsdCaptureClock {
32:     last: Option<GraphCycle>,
33:     epoch: u64,
34:     credit_secs: f64,
35: }
36: 
37: impl DsdCaptureClock {
38:     pub fn can_dequeue(&mut self, cycle: GraphCycle, epoch: u64, queue_full: bool) -> bool {
39:         self.ready(cycle, epoch) && !queue_full
40:     }
41: 
42:     /// At most one cycle of positive credit may accumulate while a source is
43:     /// idle. Negative credit retains the duration of an oversized old buffer
44:     /// during renegotiation; leaving buffers queued applies upstream backpressure.
45:     fn ready(&mut self, cycle: GraphCycle, epoch: u64) -> bool {
46:         let Some(seconds_per_tick) = cycle.seconds_per_tick() else {
47:             return false;
48:         };
49:         if self.epoch != epoch {
50:             *self = Self {
51:                 epoch,
52:                 ..Self::default()
53:             };
54:         }
55:         let ticks = match self.last {
56:             Some(last)
57:                 if last.id == cycle.id
58:                     && last.rate_num == cycle.rate_num
59:                     && last.rate_denom == cycle.rate_denom
60:                     && cycle.position >= last.position =>
61:             {
62:                 cycle.position - last.position
63:             }
64:             _ => cycle.duration,
65:         };
66:         self.last = Some(cycle);
67:         self.credit_secs = (self.credit_secs + ticks as f64 * seconds_per_tick)
68:             .min(cycle.duration as f64 * seconds_per_tick);
69:         self.credit_secs > 1e-12
70:     }
71: 
72:     pub fn consume(&mut self, bytes_per_channel: usize, byte_rate: u32) {
73:         if byte_rate > 0 {
74:             self.credit_secs -= bytes_per_channel as f64 / byte_rate as f64;
75:         }
76:     }
77: }
78: 
79: #[cfg(test)]
80: mod tests {
81:     use super::*;
82: 
