+//! Native DSD capture follows downstream consumption, not the PCM graph quantum.
+
+pub(super) struct DsdPullDemand;
+
+impl DsdPullDemand {
+    /// Units are DSD bytes per channel, including partially consumed chunks.
+    pub fn needs_buffer(buffered: u64, byte_rate: u32, cushion_ns: u64) -> bool {
+        byte_rate > 0
+            && u128::from(buffered) * 1_000_000_000
+                < u128::from(byte_rate) * u128::from(cushion_ns)
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn pulls_only_below_configured_cushion() {
+        assert!(DsdPullDemand::needs_buffer(0, 352_800, 90_000_000));
+        assert!(DsdPullDemand::needs_buffer(31_751, 352_800, 90_000_000));
+        assert!(!DsdPullDemand::needs_buffer(31_752, 352_800, 90_000_000));
+        assert!(!DsdPullDemand::needs_buffer(40_960, 352_800, 90_000_000));
+    }
+
+    #[test]
+    fn downstream_stall_cannot_accumulate_capture_credit() {
+        let mut buffered = 0;
+        let mut captured = 0;
+        for _ in 0..100_000 {
+            if DsdPullDemand::needs_buffer(buffered, 352_800, 90_000_000) {
+                buffered += 8192;
+                captured += 8192;
+            }
+        }
+        assert_eq!(captured, 32_768);
+        buffered -= 8192;
+        assert!(DsdPullDemand::needs_buffer(buffered, 352_800, 90_000_000));
+    }
+
+    #[test]
+    fn supports_rate_changes_and_large_counters_without_overflow() {
+        assert!(DsdPullDemand::needs_buffer(40_000, 705_600, 90_000_000));
+        assert!(!DsdPullDemand::needs_buffer(40_000, 352_800, 90_000_000));
+        assert!(!DsdPullDemand::needs_buffer(0, 0, 90_000_000));
+        assert!(!DsdPullDemand::needs_buffer(u64::MAX, u32::MAX, 1_000_000_000));
+    }
+}

