 use std::sync::atomic::{AtomicBool, Ordering};
+use std::time::{Duration, Instant};
+
+#[derive(Default)]
+pub(super) struct DsdPullClock {
+    next: Option<Instant>,
+}
+
+impl DsdPullClock {
+    pub fn ready(&self, now: Instant) -> bool {
+        self.next.is_none_or(|next| now >= next)
+    }
+
+    pub fn pulled(&mut self, now: Instant, units: u64, byte_rate: u32) {
+        let period = Duration::from_secs_f64(units.max(1) as f64 / byte_rate.max(1) as f64);
+        let next = self.next.unwrap_or(now);
+        // Preserve fractional timing without collecting burst credit during a
+        // downstream stall. Async sources need time to prepare the next buffer.
+        self.next = Some(if now.saturating_duration_since(next) >= period {
+            now + period
+        } else {
+            next + period
+        });
+    }
+}
