36:     _events: Box<pipewire::sys::pw_stream_events>,
37:     _pending: Arc<AtomicBool>,
38:     _stream: PhantomData<&'a pipewire::stream::Stream>,
39: }
40: 
41: impl<'a> TriggerDone<'a> {
42:     pub fn new(stream: &'a pipewire::stream::Stream, pending: Arc<AtomicBool>) -> Self {
43:         unsafe extern "C" fn done(data: *mut std::ffi::c_void) {
44:             // SAFETY: the listener owns this Arc until after unregistration.
45:             let pending = unsafe { &*data.cast::<AtomicBool>() };
46:             pending.store(false, Ordering::Release);
47:         }
48: 
49:         // SAFETY: SPA hooks and event tables support zero initialization.
50:         let mut hook = Box::new(unsafe { std::mem::zeroed() });
51:         let events = Box::new(pipewire::sys::pw_stream_events {
52:             version: pipewire::sys::PW_VERSION_STREAM_EVENTS,
53:             trigger_done: Some(done),
54:             ..unsafe { std::mem::zeroed() }
55:         });
56:         // SAFETY: all pointers are stable allocations retained by this listener;
57:         // PhantomData prevents the stream from being dropped first.
58:         unsafe {
59:             pipewire::sys::pw_stream_add_listener(
60:                 stream.as_raw_ptr(),
61:                 &mut *hook,
62:                 &*events,
63:                 Arc::as_ptr(&pending).cast_mut().cast(),
64:             );
65:         }
66:         Self {
67:             hook,
68:             _events: events,
69:             _pending: pending,
70:             _stream: PhantomData,
71:         }
72:     }
73: }
74: 
75: impl Drop for TriggerDone<'_> {
76:     fn drop(&mut self) {
77:         libspa::utils::hook::remove(*self.hook);
78:     }
79: }
